import{_ as l,a0 as o,w as d,s as r,ao as i,I as p,x as n,a1 as t,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"Python 函數式編程：不可變數據結構 | LCTT x X-CMD","titleTemplate":false,"description":"Python 函數式編程：不可變數據結構 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Python 函數式編程：不可變數據結構 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Python 函數式編程：不可變數據結構 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181004 Functional programming in Python- Immutable data structures","title":"Python 函數式編程：不可變數據結構","tag":"201811","desc":""},"relativePath":"201811/20181004 Functional programming in Python- Immutable data structures.md","filePath":"[post].md"}'),u={name:"201811/20181004 Functional programming in Python- Immutable data structures.md"};function c(g,s,h,b,k,f){const a=o("Link");return d(),r("div",null,[s[23]||(s[23]=i('<h1 id="python-函數式編程-不可變數據結構" tabindex="-1">Python 函數式編程：不可變數據結構 <a class="header-anchor" href="#python-函數式編程-不可變數據結構" aria-label="Permalink to “Python 函數式編程：不可變數據結構”">​</a></h1><blockquote><p>不可變性可以幫助我們更好地理解我們的代碼。下面我將講述如何在不犧牲性能的條件下來實現它。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/metrics_graph_stats_blue.png?itok=OKCc_60D" alt=""></p><p>在這個由兩篇文章構成的系列中，我將討論如何將函數式編程方法論中的思想引入至 Python 中，來充分發揮這兩個領域的優勢。</p><p>本文（也就是第一篇文章）中，我們將探討不可變數據結構的優勢。第二部分會探討如何在 <code>toolz</code> 庫的幫助下，用 Python 實現高層次的函數式編程理念。</p><p>為什麼要用函數式編程？因為變化的東西更難推理。如果你已經確信變化會帶來麻煩，那很棒。如果你還沒有被説服，在文章結束時，你會明白這一點的。</p><p>我們從思考正方形和矩形開始。如果我們拋開實現細節，單從接口的角度考慮，正方形是矩形的子類嗎？</p>',7)),p("p",null,[s[1]||(s[1]=n("子類的定義基於",-1)),t(a,{href:"https://en.wikipedia.org/wiki/Liskov_substitution_principle"},{default:e(()=>[...s[0]||(s[0]=[n("里氏替換原則",-1)])]),_:1}),s[2]||(s[2]=n("。一個子類必須能夠完成超類所做的一切。",-1))]),s[24]||(s[24]=i(`<p>如何為矩形定義接口？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from zope.interface import Interface</span></span>
<span class="line"><span></span></span>
<span class="line"><span>class IRectangle(Interface):</span></span>
<span class="line"><span>    def get_length(self):</span></span>
<span class="line"><span>        &quot;&quot;&quot;正方形能做到&quot;&quot;&quot;</span></span>
<span class="line"><span>    def get_width(self):</span></span>
<span class="line"><span>        &quot;&quot;&quot;正方形能做到&quot;&quot;&quot;</span></span>
<span class="line"><span>    def set_dimensions(self, length, width):</span></span>
<span class="line"><span>        &quot;&quot;&quot;啊哦&quot;&quot;&quot;</span></span></code></pre></div><p>如果我們這麼定義，那正方形就不能成為矩形的子類：如果長度和寬度不等，它就無法對 <code>set_dimensions</code> 方法做出響應。</p><p>另一種方法，是選擇將矩形做成不可變對象。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class IRectangle(Interface):</span></span>
<span class="line"><span>    def get_length(self):</span></span>
<span class="line"><span>        &quot;&quot;&quot;正方形能做到&quot;&quot;&quot;</span></span>
<span class="line"><span>    def get_width(self):</span></span>
<span class="line"><span>        &quot;&quot;&quot;正方形能做到&quot;&quot;&quot;</span></span>
<span class="line"><span>    def with_dimensions(self, length, width):</span></span>
<span class="line"><span>        &quot;&quot;&quot;返回一個新矩形&quot;&quot;&quot;</span></span></code></pre></div><p>現在，我們可以將正方形視為矩形了。在調用 <code>with_dimensions</code> 時，它可以返回一個新的矩形（它不一定是個正方形），但它本身並沒有變，依然是一個正方形。</p><p>這似乎像是個學術問題 —— 直到我們認為正方形和矩形可以在某種意義上看做一個容器的側面。在理解了這個例子以後，我們會處理更傳統的容器，以解決更現實的案例。比如，考慮一下隨機存取數組。</p><p>我們現在有 <code>ISquare</code> 和 <code>IRectangle</code>，而且 <code>ISequere</code> 是 <code>IRectangle</code> 的子類。</p><p>我們希望把矩形放進隨機存取數組中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class IArrayOfRectangles(Interface):</span></span>
<span class="line"><span>    def get_element(self, i):</span></span>
<span class="line"><span>        &quot;&quot;&quot;返回一個矩形&quot;&quot;&quot;</span></span>
<span class="line"><span>    def set_element(self, i, rectangle):</span></span>
<span class="line"><span>        &quot;&quot;&quot;&#39;rectangle&#39; 可以是任意 IRectangle 對象&quot;&quot;&quot;</span></span></code></pre></div><p>我們同樣希望把正方形放進隨機存取數組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class IArrayOfSquare(Interface):</span></span>
<span class="line"><span>    def get_element(self, i):</span></span>
<span class="line"><span>        &quot;&quot;&quot;返回一個正方形&quot;&quot;&quot;</span></span>
<span class="line"><span>    def set_element(self, i, square):</span></span>
<span class="line"><span>        &quot;&quot;&quot;&#39;square&#39; 可以是任意 ISquare 對象&quot;&quot;&quot;</span></span></code></pre></div><p>儘管 <code>ISquare</code> 是 <code>IRectangle</code> 的子集，但沒有任何一個數組可以同時實現 <code>IArrayOfSquare</code> 和 <code>IArrayOfRectangle</code>.</p><p>為什麼不能呢？假設 <code>bucket</code> 實現了這兩個類的功能。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; rectangle = make_rectangle(3, 4)</span></span>
<span class="line"><span>&gt;&gt;&gt; bucket.set_element(0, rectangle) # 這是 IArrayOfRectangle 中的合法操作</span></span>
<span class="line"><span>&gt;&gt;&gt; thing = bucket.get_element(0) # IArrayOfSquare 要求 thing 必須是一個正方形</span></span>
<span class="line"><span>&gt;&gt;&gt; assert thing.height == thing.width</span></span>
<span class="line"><span>Traceback (most recent call last):</span></span>
<span class="line"><span>  File &quot;&lt;stdin&gt;&quot;, line 1, in &lt;module&gt;</span></span>
<span class="line"><span>AssertionError</span></span></code></pre></div><p>無法同時實現這兩類功能，意味着這兩個類無法構成繼承關係，即使 <code>ISquare</code> 是 <code>IRectangle</code> 的子類。問題來自 <code>set_element</code> 方法：如果我們實現一個只讀的數組，那 <code>IArrayOfSquare</code> 就可以是 <code>IArrayOfRectangle</code> 的子類了。</p><p>在可變的 <code>IRectangle</code> 和可變的 <code>IArrayOf*</code> 接口中，可變性都會使得對類型和子類的思考變得更加困難 —— 放棄變換的能力，意味着我們的直覺所希望的類型間關係能夠成立了。</p><p>可變性還會帶來作用域方面的影響。當一個共享對象被兩個地方的代碼改變時，這種問題就會發生。一個經典的例子是兩個線程同時改變一個共享變量。不過在單線程程序中，即使在兩個相距很遠的地方共享一個變量，也是一件簡單的事情。從 Python 語言的角度來思考，大多數對象都可以從很多位置來訪問：比如在模組全局變量，或在一個堆棧跟蹤中，或者以類屬性來訪問。</p><p>如果我們無法對共享做出約束，那我們可能要考慮對可變性來進行約束了。</p>`,19)),p("p",null,[s[4]||(s[4]=n("這是一個不可變的矩形，它利用了 ",-1)),t(a,{href:"https://www.attrs.org/en/stable/"},{default:e(()=>[...s[3]||(s[3]=[n("attr",-1)])]),_:1}),s[5]||(s[5]=n(" 庫：",-1))]),s[25]||(s[25]=i(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@attr.s(frozen=True)</span></span>
<span class="line"><span>class Rectange(object):</span></span>
<span class="line"><span>    length = attr.ib()</span></span>
<span class="line"><span>    width = attr.ib()</span></span>
<span class="line"><span>    @classmethod</span></span>
<span class="line"><span>    def with_dimensions(cls, length, width):</span></span>
<span class="line"><span>        return cls(length, width)</span></span></code></pre></div><p>這是一個正方形：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@attr.s(frozen=True)</span></span>
<span class="line"><span>class Square(object):</span></span>
<span class="line"><span>    side = attr.ib()</span></span>
<span class="line"><span>    @classmethod</span></span>
<span class="line"><span>    def with_dimensions(cls, length, width):</span></span>
<span class="line"><span>        return Rectangle(length, width)</span></span></code></pre></div><p>使用 <code>frozen</code> 參數，我們可以輕易地使 <code>attrs</code> 創建的類成為不可變類型。正確實現 <code>__setitem__</code> 方法的工作都交給別人完成了，對我們是不可見的。</p><p>修改對象仍然很容易；但是我們不可能改變它的本質。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>too_long = Rectangle(100, 4)</span></span>
<span class="line"><span>reasonable = attr.evolve(too_long, length=10)</span></span></code></pre></div>`,6)),p("p",null,[t(a,{href:"https://pyrsistent.readthedocs.io/en/latest/"},{default:e(()=>[...s[6]||(s[6]=[n("Pyrsistent",-1)])]),_:1}),s[7]||(s[7]=n(" 能讓我們擁有不可變的容器。",-1))]),s[26]||(s[26]=i(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 由整數構成的向量</span></span>
<span class="line"><span>a = pyrsistent.v(1, 2, 3)</span></span>
<span class="line"><span># 並非由整數構成的向量</span></span>
<span class="line"><span>b = a.set(1, &quot;hello&quot;)</span></span></code></pre></div><p>儘管 <code>b</code> 不是一個由整數構成的向量，但沒有什麼能夠改變 <code>a</code> 只由整數構成的性質。</p><p>如果 <code>a</code> 有一百萬個元素呢？<code>b</code> 會將其中的 999999 個元素複製一遍嗎？<code>Pyrsistent</code> 具有“大 O”性能保證：所有操作的時間複雜度都是 <code>O(log n)</code>. 它還帶有一個可選的 C 語言擴展，以在“大 O”性能之上進行提升。</p><p>修改嵌套對象時，會涉及到“變換器”的概念：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>blog = pyrsistent.m(</span></span>
<span class="line"><span>    title=&quot;My blog&quot;,</span></span>
<span class="line"><span>    links=pyrsistent.v(&quot;github&quot;, &quot;twitter&quot;),</span></span>
<span class="line"><span>    posts=pyrsistent.v(</span></span>
<span class="line"><span>        pyrsistent.m(title=&quot;no updates&quot;,</span></span>
<span class="line"><span>                     content=&quot;I&#39;m busy&quot;),</span></span>
<span class="line"><span>        pyrsistent.m(title=&quot;still no updates&quot;,</span></span>
<span class="line"><span>                     content=&quot;still busy&quot;)))</span></span>
<span class="line"><span>new_blog = blog.transform([&quot;posts&quot;, 1, &quot;content&quot;],</span></span>
<span class="line"><span>                          &quot;pretty busy&quot;)</span></span></code></pre></div><p><code>new_blog</code> 現在將是如下對象的不可變等價物：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{&#39;links&#39;: [&#39;github&#39;, &#39;twitter&#39;],</span></span>
<span class="line"><span> &#39;posts&#39;: [{&#39;content&#39;: &quot;I&#39;m busy&quot;,</span></span>
<span class="line"><span>            &#39;title&#39;: &#39;no updates&#39;},</span></span>
<span class="line"><span>           {&#39;content&#39;: &#39;pretty busy&#39;,</span></span>
<span class="line"><span>            &#39;title&#39;: &#39;still no updates&#39;}],</span></span>
<span class="line"><span> &#39;title&#39;: &#39;My blog&#39;}</span></span></code></pre></div><p>不過 <code>blog</code> 依然不變。這意味着任何擁有舊對象引用的人都沒有受到影響：轉換隻會有局部效果。</p><p>當共享行為猖獗時，這會很有用。例如，函數的默認參數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def silly_sum(a, b, extra=v(1, 2)):</span></span>
<span class="line"><span>    extra = extra.extend([a, b])</span></span>
<span class="line"><span>    return sum(extra)</span></span></code></pre></div><p>在本文中，我們瞭解了為什麼不可變性有助於我們來思考我們的代碼，以及如何在不帶來過大性能負擔的條件下實現它。下一篇，我們將學習如何藉助不可變對象來實現強大的程序結構。</p><hr>`,12)),p("p",null,[s[9]||(s[9]=n("via: ",-1)),t(a,{href:"https://opensource.com/article/18/10/functional-programming-python-immutable-data-structures"},{default:e(()=>[...s[8]||(s[8]=[n("https://opensource.com/article/18/10/functional-programming-python-immutable-data-structures",-1)])]),_:1})]),p("p",null,[s[14]||(s[14]=n("作者：",-1)),t(a,{href:"https://opensource.com/users/moshez"},{default:e(()=>[...s[10]||(s[10]=[n("Moshe Zadka",-1)])]),_:1}),s[15]||(s[15]=n(" 選題：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[11]||(s[11]=[n("lujun9972",-1)])]),_:1}),s[16]||(s[16]=n(" 譯者：",-1)),t(a,{href:"https://github.com/StdioA"},{default:e(()=>[...s[12]||(s[12]=[n("StdioA",-1)])]),_:1}),s[17]||(s[17]=n(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[13]||(s[13]=[n("wxy",-1)])]),_:1})]),p("p",null,[s[20]||(s[20]=n("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[18]||(s[18]=[n("LCTT",-1)])]),_:1}),s[21]||(s[21]=n(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:e(()=>[...s[19]||(s[19]=[n("Linux中國",-1)])]),_:1}),s[22]||(s[22]=n(" 榮譽推出",-1))])])}const _=l(u,[["render",c]]);export{y as __pageData,_ as default};
